int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    int x, q;
    cin >> s >> x >> q;
    vector<int> queries(q);
    for (int i = 0; i < q; i++) cin >> queries[i];
    vector<bool> res = answerQueries(s, x, queries);
    string out;
    for (size_t i = 0; i < res.size(); i++) out += res[i] ? "YES\n" : "NO\n";
    cout << out;
