import java.util.*;
import java.io.*;

public class Main {
    static boolean[] answerQueries(String s, int x, int[] queries) {
        // Write your solution here
        return new boolean[queries.length];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        String s = st.nextToken();
        int x = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        int[] queries = new int[q];
        for (int i = 0; i < q; i++) queries[i] = Integer.parseInt(st.nextToken());
        boolean[] res = answerQueries(s, x, queries);
        StringBuilder sb = new StringBuilder();
        for (boolean r : res) sb.append(r ? "YES" : "NO").append('\n');
        System.out.print(sb);
    }
}
